  $s like ".*Accenture.*";
  $org isa organization, has revenue $r;
  $r > 50000000.0;
  ceo_of (ceo: $ceo, organization: $org);
sort $r desc;
limit 3;
fetch {
  "name": $org.name,
  "revenue": $r
};

match
