with fun latest_article_date($o: organization) -> datetime:
  match
    mentions (article: $a, mentioned: $o);
    $a has date $d;
  return max($d);
match
  $o isa organization;
  let $max_date = latest_article_date($o);
  mentions (article: $a, mentioned: $o);
  $a has date $d;
  $d == $max_date;
  $a has sentiment $s;
  $s > 0.8;
fetch {
  "organization_name": $o.name,
  "sentiment_score": $s,
  "article_date": $d
};

match
$org isa organization, has name $org_name;
$ceo isa person, has name $ceo_name;
ceo_of (organization: $org, ceo: $ceo);
$article isa article, has title $article_title, has author $author;
$ceo_name == $author;
fetch {
  "OrganizationName": $org_name,
  "CEOName": $ceo_name,
  "ArticleTitle": $article_title
};

match
$o isa organization, has name $name;
competes_with ($o, $c);
$c isa organization;
not { $o is $c; };
reduce $count = count($c) groupby $o, $name;
match $count > 2;
fetch { "organizationName": $name, "competitorCount": $count };

